from rest_framework import viewsets, permissions
from rest_framework.decorators import action
from rest_framework.response import Response
from .models import PayrollBatch, PayrollLineItem
from .serializers import PayrollBatchSerializer

class PayrollBatchViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = PayrollBatchSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return PayrollBatch.objects.filter(company=self.request.user.company)

    @action(detail=True, methods=["get"])
    def line_items(self, request, pk=None):
        batch = self.get_object()
        items = PayrollLineItem.objects.filter(batch=batch)
        data = [
            {"id": item.id, "employee_name": item.employee_name, "net_pay": str(item.net_pay)}
            for item in items
        ]
        return Response({"batch_id": batch.id, "items": data})
